adcs_status_t status;
adcs_quat_t q_pred_norm, q_meas_norm;
double dot_val, angle;
int is_fault = 0;

/* 1. Input Validation: NULL pointers, enable flag, config ranges */
if (st_input.predicted == NULL || st_input.measured == NULL) {
    is_fault = 1;
} else if (st_input.enable != 0 && st_input.enable != 1) {
    is_fault = 1;
} else if (st_config.accept_rad < 0.0 || st_config.reject_rad > ADCS_PI ||
           st_config.accept_rad >= st_config.reject_rad ||
           st_config.max_rejects < 1U || st_config.max_rejects > 20U) {
    is_fault = 1;
} else if (!isfinite(st_config.accept_rad) || !isfinite(st_config.reject_rad)) {
    is_fault = 1;
} else if (!isfinite(st_input.predicted->w) || !isfinite(st_input.predicted->x) ||
           !isfinite(st_input.predicted->y) || !isfinite(st_input.predicted->z) ||
           !isfinite(st_input.measured->w) || !isfinite(st_input.measured->x) ||
           !isfinite(st_input.measured->y) || !isfinite(st_input.measured->z)) {
    is_fault = 1;
}

if (is_fault) {
    st_state.mode = ST_FAULT;
    st_output.mode = ST_FAULT;
    st_output.rejects = st_state.rejects;
    st_output.innovation_rad = 0.0;
    st_output.axis.x = 0.0;
    st_output.axis.y = 0.0;
    st_output.axis.z = 0.0;
    return;
}

/* 2. Normalize Quaternions */
status = adcs_quat_normalize(st_input.predicted, &q_pred_norm);
if (status != ADCS_OK) {
    st_state.mode = ST_FAULT;
    st_output.mode = ST_FAULT;
    st_output.rejects = st_state.rejects;
    st_output.innovation_rad = 0.0;
    st_output.axis.x = 0.0;
    st_output.axis.y = 0.0;
    st_output.axis.z = 0.0;
    return;
}

status = adcs_quat_normalize(st_input.measured, &q_meas_norm);
if (status != ADCS_OK) {
    st_state.mode = ST_FAULT;
    st_output.mode = ST_FAULT;
    st_output.rejects = st_state.rejects;
    st_output.innovation_rad = 0.0;
    st_output.axis.x = 0.0;
    st_output.axis.y = 0.0;
    st_output.axis.z = 0.0;
    return;
}

/* 3. Compute Innovation Angle: sign-invariant shortest angle */
/* q_measured and q_predicted are unit quaternions. 
   The angle between them is 2 * acos(|dot(q1, q2)|). */
dot_val = adcs_quat_abs_dot(&q_pred_norm, &q_meas_norm);
if (dot_val > 1.0) dot_val = 1.0;
angle = 2.0 * acos(dot_val);

/* 4. Decision Logic with Hysteresis */
if (st_input.enable == 0) {
    /* Disabled: Force ACCEPT, clear evidence */
    st_state.mode = ST_ACCEPT;
    st_state.rejects = 0;
} else if (angle <= st_config.accept_rad) {
    /* Acceptable: ACCEPT, clear evidence */
    st_state.mode = ST_ACCEPT;
    st_state.rejects = 0;
} else if (angle >= st_config.reject_rad) {
    /* Reject threshold reached: REJECT, increment count */
    st_state.mode = ST_REJECT;
    st_state.rejects++;
    if (st_state.rejects > st_config.max_rejects) {
        st_state.mode = ST_FAULT;
    }
}
/* Else: Hysteresis band (accept_rad < angle < reject_rad), preserve state */

/* 5. Update Outputs */
st_output.mode = st_state.mode;
st_output.rejects = st_state.rejects;
st_output.innovation_rad = angle;

if (st_state.mode != ST_FAULT) {
    adcs_quat_t q_pred_conj;
    adcs_quat_t q_rel;
    adcs_vec3_t axis_raw;

    /* Relative rotation: q_rel = q_measured * conjugate(q_predicted) */
    q_pred_conj = adcs_quat_conjugate(&q_pred_norm);
    q_rel = adcs_quat_multiply(&q_meas_norm, &q_pred_conj);

    /* Extract axis from quaternion w,x,y,z -> x,y,z */
    axis_raw.x = q_rel.x;
    axis_raw.y = q_rel.y;
    axis_raw.z = q_rel.z;

    /* Normalize axis vector */
    status = adcs_vec3_normalize(&axis_raw, FLT64_ZERO, &st_output.axis);
    if (status != ADCS_OK) {
        /* Degenerate case (zero rotation), set axis to zero */
        st_output.axis.x = 0.0;
        st_output.axis.y = 0.0;
        st_output.axis.z = 0.0;
    }
} else {
    st_output.innovation_rad = 0.0;
    st_output.axis.x = 0.0;
    st_output.axis.y = 0.0;
    st_output.axis.z = 0.0;
}

